declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('POST');$in=production_input();accounts_endpoint(function()use($user,$in):array{$db=production_db();return accounts_transaction($db,function()use($db,$user,$in):array{$i=billing_invoice_outstanding($db,(int)($in['invoice_id']??0),true);if($i['status']!=='ISSUED'||$i['outstanding_minor']!==accounts_money_minor($i['total_amount'],false))accounts_fail('ONLY_UNPAID_INVOICE_CAN_BE_VOIDED',409);$reason=production_clean_text($in['reason']??'',500,'REASON_REQUIRED');$rev=accounts_reverse_journal($db,$user,(int)$i['journal_id'],$reason,accounts_date($in['void_date']??gmdate('Y-m-d')));$db->prepare("UPDATE qbook_invoices SET status='VOID',voided_at=UTC_TIMESTAMP(),voided_by=?,void_reason=? WHERE id=?")->execute([$user['id'],$reason,$i['id']]);$db->prepare("UPDATE qbook_invoice_production_allocations pa JOIN qbook_invoice_lines l ON l.id=pa.invoice_line_id SET pa.status='REVERSED' WHERE l.invoice_id=? AND pa.status='COMMITTED'")->execute([$i['id']]);accounts_audit($db,$user,'INVOICE_VOIDED','INVOICE',$i['id'],['reversal_journal_id'=>$rev['id'],'reason'=>$reason]);return['invoice'=>['id'=>(int)$i['id'],'status'=>'VOID'],'reversal'=>$rev];});});
